import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static int N, LOG;
    static int[] parent, depth, tin, tout, nodeAtTin;
    static int[][] up;
    static List<List<Integer>> children;

    static int kthAncestor(int u, int k) {
        for (int j = 0; j < LOG; j++) {
            if (((k >> j) & 1) == 1) {
                u = up[j][u];
                if (u == 0) return 0;
            }
        }
        return u;
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        N = fs.nextInt();

        parent = new int[N + 1];
        depth = new int[N + 1];
        children = new ArrayList<>(N + 1);
        for (int i = 0; i <= N; i++) children.add(new ArrayList<>());

        parent[1] = 0;
        depth[1] = 0;

        for (int i = 2; i <= N; i++) {
            parent[i] = fs.nextInt();
            children.get(parent[i]).add(i);
            depth[i] = depth[parent[i]] + 1;
        }

        LOG = 1;
        while ((1 << LOG) <= N) LOG++;
        LOG++;

        up = new int[LOG][N + 1];
        for (int i = 1; i <= N; i++) up[0][i] = parent[i];

        for (int j = 1; j < LOG; j++) {
            for (int i = 1; i <= N; i++) {
                int mid = up[j - 1][i];
                up[j][i] = (mid == 0) ? 0 : up[j - 1][mid];
            }
        }

        tin = new int[N + 1];
        tout = new int[N + 1];
        nodeAtTin = new int[N + 1];

        int timer = 0;
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(1);

        while (!stack.isEmpty()) {
            int u = stack.pop();
            if (u > 0) {
                tin[u] = ++timer;
                nodeAtTin[timer] = u;
                stack.push(-u);

                List<Integer> ch = children.get(u);
                for (int i = ch.size() - 1; i >= 0; i--) {
                    stack.push(ch.get(i));
                }
            } else {
                u = -u;
                tout[u] = timer;
            }
        }

        TreeSet<Integer> activeTins = new TreeSet<>();
        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int type = fs.nextInt();
            int v = fs.nextInt();

            if (type == 1) {
                int k = fs.nextInt();

                Integer t = activeTins.floor(tin[v]);
                int activeAncestor = 0;

                if (t != null) {
                    int u = nodeAtTin[t];
                    if (tout[u] >= tin[v]) {
                        activeAncestor = u;
                    }
                }

                int ans;
                if (activeAncestor != 0 && activeAncestor != v) {
                    if (k == 1) {
                        ans = activeAncestor;
                    } else {
                        ans = kthAncestor(activeAncestor, k - 1);
                    }
                } else {
                    ans = kthAncestor(v, k);
                }

                sb.append(ans).append('\n');
            } else {
                Integer t = activeTins.floor(tin[v]);
                boolean underActive = false;

                if (t != null) {
                    int u = nodeAtTin[t];
                    if (tout[u] >= tin[v]) {
                        underActive = true;
                    }
                }

                if (!underActive) {
                    NavigableSet<Integer> sub = activeTins.subSet(tin[v], true, tout[v], true);
                    Iterator<Integer> it = sub.iterator();
                    while (it.hasNext()) {
                        it.next();
                        it.remove();
                    }
                    activeTins.add(tin[v]);
                }
            }
        }

        System.out.print(sb.toString());
    }
}
